/** 
 * Reported bug: When Breaker of Armies is granted Menace and there is only 1 valid blocker, the game enters a state that cannot be continued. He must be blocked by all creatures that are able, however, with menace the only valid blocks would be by more than one creature, so the expected behavior is no blocks can be made.
 */
@Test public void testBreakerOfArmiesWithMenace(){
  addCard(Zone.BATTLEFIELD,playerA,"Breaker of Armies",1);
  addCard(Zone.BATTLEFIELD,playerB,"Hill Giant",1);
  addCard(Zone.BATTLEFIELD,playerA,"Swamp",8);
  addCard(Zone.HAND,playerA,"Untamed Hunger",1);
  castSpell(1,PhaseStep.PRECOMBAT_MAIN,playerA,"Untamed Hunger","Breaker of Armies");
  attack(1,playerA,"Breaker of Armies");
  block(1,playerB,"Hill Giant","Breaker of Armies");
  setStopAt(1,PhaseStep.POSTCOMBAT_MAIN);
  try {
    execute();
  } catch (NullPointerException | ClassCastException e) {
    e.printStackTrace();
    fail("Unexpected exception during test execution: " + e.getMessage());
  }
  assertPermanentCount(playerB,"Hill Giant",1);
  assertLife(playerB,8);
}
